using UnityEngine;

namespace Mottainai
{
    /// Art-direction tokens (ART_DIRECTION.md §2). Asset: Resources/DesignTokens (generated by Setup Project); code defaults otherwise.
    public class DesignTokens : ScriptableObject
    {
        public Color primary = Hex(0x62C96B);        // Eco Green: PLAY, validated, progress
        public Color water = Hex(0x21B8C7);          // River Cyan
        public Color waterShadow = Hex(0x167E9B);
        public Color waterShallow = Hex(0x72D6E7);
        public Color accentLime = Hex(0xA8DF70);
        public Color reward = Hex(0xFFC857);         // Sun Yellow
        public Color alert = Hex(0xFF8360);          // Coral
        public Color textDark = Hex(0x244A53);       // Deep Teal (panels 88-95%)
        public Color panelLight = Hex(0xF5FAF7);     // Cloud
        public Color playTop = Hex(0x8BE66F), playBottom = Hex(0x42BF62);
        public Color boostTop = Hex(0xFFC857), boostBottom = Hex(0xFF9E45);
        public Color secondary = Hex(0x21B8C7);
        public float radiusS = 10f, radiusM = 16f, radiusL = 24f;
        public float pressScale = 0.96f, transition = 0.2f;
        // role cap colors (pink reserved for future modes)
        public Color capLeft = Hex(0x2F8CFF), capRight = Hex(0x3DBB4E), capCollector = Hex(0xFFD23F), capPink = Hex(0xFF7EB6);
        public Color vest = Hex(0xFF8A1F);

        static DesignTokens current;
        public static DesignTokens Current
        {
            get
            {
                if (current != null) return current;
                current = Resources.Load<DesignTokens>("DesignTokens");
                if (current == null) current = CreateInstance<DesignTokens>();
                return current;
            }
        }

        public static Color Hex(int rgb, float a = 1f) => new Color(((rgb >> 16) & 0xFF) / 255f, ((rgb >> 8) & 0xFF) / 255f, (rgb & 0xFF) / 255f, a);
    }

    /// Visual quality tier: High (post, caustics, extra particles) / Low. Persisted, default from device class.
    public static class Quality
    {
        static int high = -1;
        public static event System.Action Changed;

        public static bool High
        {
            get
            {
                if (high < 0) high = PlayerPrefs.GetInt("qualityHigh", DefaultHigh() ? 1 : 0);
                return high == 1;
            }
            set
            {
                high = value ? 1 : 0;
                PlayerPrefs.SetInt("qualityHigh", high);
                PlayerPrefs.Save();
                Changed?.Invoke();
            }
        }

        static bool DefaultHigh() => !Application.isMobilePlatform || (SystemInfo.systemMemorySize >= 5500 && SystemInfo.processorCount >= 8);
    }
}
